const ctx = $('Validate Input').first().json;
const cust = $('Upsert Customer').first().json;
const ai = $input.first().json;
const map = { sales: 'sales_agent', support: 'support_agent', billing: 'billing_agent', human: 'human_escalation', unknown: 'human_escalation' };
const LOW_CONFIDENCE = 0.6;
let intent = 'unknown';
let confidence = 0;
let reason = 'classification failed';
try {
  let content = ai.choices[0].message.content;
  content = content.replace(/```json|```/g, '').trim();
  const p = JSON.parse(content);
  if (map[p.intent]) intent = p.intent;
  confidence = Math.max(0, Math.min(1, Number(p.confidence) || 0));
  reason = String(p.reason || '').slice(0, 500);
} catch (e) {
  const apiErr = ai.error && ai.error.message ? ai.error.message : e.message;
  reason = 'Classifier output invalid or LLM call failed: ' + apiErr;
  intent = 'unknown';
  confidence = 0;
}
let specialist = map[intent];
if (confidence < LOW_CONFIDENCE && specialist !== 'human_escalation') {
  reason += ' | low confidence -> human_escalation';
  specialist = 'human_escalation';
}
const needs_human = specialist === 'human_escalation';
return [{ json: {
  customer_id: cust.id,
  customer_external_id: ctx.customer_external_id,
  message_id: ctx.message_id,
  message: ctx.message,
  supabase_url: ctx.supabase_url,
  intent,
  confidence,
  routing_reason: reason,
  selected_specialist: specialist,
  needs_human
} }];
